class Solution {
public:
    int longestSubarray(vector<int>& nums) {
        int n = nums.size(), run = 2, best = min(n, 2);
        for (int i = 2; i < n; ++i) {
            if (1LL * nums[i - 2] + nums[i - 1] == nums[i]) ++run;
            else run = 2;
            best = max(best, run);
        }
        return best;
    }
};
